//
// Health-risk example — decrypt the result (patient side, CKKS)
//
// Prints the patient's 10-year risk as a fraction on one line, e.g.
// "risk 0.1675018234", so scripts can parse it. Turning it into a percentage
// and a risk band is the caller's job (run_test.sh, the demo client).
//
// Usage: ./health_risk_decrypt <client_home> <ct_result.bin>

#include "openfhe.h"

#include <iomanip>

#include "ciphertext-ser.h"
#include "cryptocontext-ser.h"
#include "key/key-ser.h"
#include "scheme/ckksrns/ckksrns-ser.h"

using namespace lbcrypto;

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " <client_home> <ct_result.bin>" << std::endl;
        return 2;
    }
    const std::string home = argv[1];

    CryptoContext<DCRTPoly> cc;
    if (!Serial::DeserializeFromFile(home + "/cc.bin", cc, SerType::BINARY))
        throw std::runtime_error("Failed to load crypto context");
    PrivateKey<DCRTPoly> sk;
    if (!Serial::DeserializeFromFile(home + "/sk.bin", sk, SerType::BINARY))
        throw std::runtime_error("Failed to load secret key");
    Ciphertext<DCRTPoly> ct;
    if (!Serial::DeserializeFromFile(argv[2], ct, SerType::BINARY))
        throw std::runtime_error("Failed to load result ciphertext");

    Plaintext pt;
    cc->Decrypt(sk, ct, &pt);
    pt->SetLength(1);
    std::cout << "risk " << std::setprecision(10) << std::fixed
              << pt->GetRealPackedValue()[0] << std::endl;
    return 0;
}
